const input=$json.body??$json;
const dealId=input.deal_id??input.dealId, leadId=input.lead_id??input.leadId, propertyId=input.property_id??input.propertyId;
const providerMessageId=input.provider_message_id??input.providerMessageId;
const monitoringKey=input.monitoring_idempotency_key??input.delivery_idempotency_key??input.idempotency_key;
const eventType=String(input.event_type??input.eventType??'').toLowerCase();
const response= input.seller_response??input.inbound_seller_response??input.inbound_message??null;
const responseText=String(typeof response==='string'?response:(response?.text??'' )).trim();
const timeout=Boolean(input.response_timeout||eventType==='timeout');
const deliveryFailed=['failed','bounced','rejected','undeliverable'].includes(String(input.provider_status??input.delivery_status??'').toLowerCase());
const dnc=Boolean(input.dnc||input.do_not_contact||input.opted_out);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const attempts=Number(input.attempts??0), maxAttempts=Number(input.max_attempts??5);
const identityValid=Boolean(dealId&&leadId&&propertyId&&providerMessageId&&monitoringKey);
const eventKey=monitoringKey&&providerMessageId&&eventType?\`${monitoringKey}:event:${providerMessageId}:${eventType}\`:null;
let decision='monitor',route='WF-361',reason='Seller response monitoring remains active.';
if(dnc){decision='hard_stop';route='WF-126';reason='DNC/opt-out detected; stop automated seller outreach.'}
else if(blockers.length){decision='blocked';route='WF-126';reason='Operational blockers require controlled human handling.'}
else if(!identityValid){decision='reconcile';route='WF-360';reason='Required monitoring/provider identity is missing; reconcile before continuation.'}
else if(responseText){decision='seller_response';route='WF-342';reason='Seller response event received; classify and route the response.'}
else if(timeout){decision=attempts<maxAttempts?'timeout_followup':'max_attempts';route=attempts<maxAttempts?'WF-352':'WF-126';reason=attempts<maxAttempts?'Response window expired; evaluate controlled follow-up.':'Maximum outreach attempts reached; require human control.'}
else if(deliveryFailed){decision='delivery_failure';route='WF-350';reason='Delivery failure detected; route to controlled retry/re-engagement.'}
else {decision='monitor';route='WF-361';reason='No actionable seller event; continue monitoring.'}
return [{json:{workflow:'WF-369',decision,route,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,provider_message_id:providerMessageId,event_type:eventType,response_text:responseText,response_timeout:timeout,delivery_failed:deliveryFailed,attempts,max_attempts:maxAttempts,dnc,blockers,monitoring_idempotency_key:monitoringKey,event_idempotency_key:eventKey,identity_valid:identityValid,next_action:route==='WF-342'?'classify_seller_response':route==='WF-352'?'evaluate_follow_up':route==='WF-350'?'controlled_retry_or_reengagement':route==='WF-361'?'continue_response_monitoring':'human_control',audit_event:'seller_response_monitoring_timeout_or_response_event'}}];
